// Purpose: the whole story, chapter by chapter, written as data: where the floors, walls and
// gates are, what each character can use, and the rules that turn events into scenes.
// The engine in game.js reads this; a writer or level designer can change the story here
// without touching any engine code.
//
// Coordinates: x grows to the right, y grows downward. In two-floor chapters the upper floor's
// surface is at y = 300 (her route) and the lower floor's at y = 520 (the dog's route).
'use strict';

// Who the story is about. The dog's name is assumed from the project's name; change it here
// and every line of the story updates. Pronouns: use "her"/"her", "him"/"his" or "them"/"their".
const story_config = {
    dog_name: 'Bodhi',
    her_name: 'Em',   // Blonde, blue eyes. Filled into {her}; see docs/characters.md.
    dog_object_pronoun: 'him',
    dog_possessive_pronoun: 'his',
};

// How Bodhi grows through the story, one stage per chapter (a chapter names its stage with
// `dog_age`). Goldendoodles grow fast: about full height at a year.
//   label: shown on the chapter card.
//   size: his height compared with a grown goldendoodle (1). His collision box and drawing
//     both scale by it, so a puppy fits through gaps a grown dog can't.
//   drawing: which set of hand-drawn frames shows him: 'bodhi_puppy' (big head, short legs)
//     until about six months, then 'bodhi' (the grown build, drawn smaller while he grows).
//   jump: how high he jumps compared with a grown dog.
const dog_growth = {
    eight_weeks: { label: '8 weeks old', size: 0.46, drawing: 'bodhi_puppy', jump: 0.8 },
    four_months: { label: '4 months old', size: 0.6, drawing: 'bodhi_puppy', jump: 0.88 },
    five_months: { label: '5 months old', size: 0.66, drawing: 'bodhi_puppy', jump: 0.92 },
    six_months: { label: '6 months old', size: 0.74, drawing: 'bodhi', jump: 1 },
    six_and_a_half_months: { label: '6\u00bd months old', size: 0.77, drawing: 'bodhi', jump: 1 },
    seven_months: { label: '7 months old', size: 0.8, drawing: 'bodhi', jump: 1 },
    eight_months: { label: '8 months old', size: 0.84, drawing: 'bodhi', jump: 1 },
    nine_months: { label: '9 months old', size: 0.88, drawing: 'bodhi', jump: 1 },
    ten_months: { label: '10 months old', size: 0.915, drawing: 'bodhi', jump: 1 },
    eleven_months: { label: '11 months old', size: 0.95, drawing: 'bodhi', jump: 1 },
    eleven_and_a_half_months: { label: '11\u00bd months old', size: 0.975, drawing: 'bodhi', jump: 1 },
    one_year: { label: 'one year old', size: 1, drawing: 'bodhi', jump: 1 },
};

// Shorthand for building chapters. A "floor block" is solid from its top down to the bottom
// of the world; a "slab" is a thin floor with open space underneath.
function floor_block(x, top, width) {
    return { kind: 'floor', x: x, y: top, w: width, h: 620 - top };
}
function slab(x, width) {
    return { kind: 'floor', x: x, y: 300, w: width, h: 30 };
}

